      const row = this.database.prepare(`SELECT * FROM follow_ups WHERE ((status IN ('scheduled', 'retrying') AND due_at <= ?) OR (status = 'claimed' AND claimed_at <= ?)) ORDER BY due_at ASC LIMIT 1`).get(timestamp, cutoff) as Row | undefined;
